/**
 * Generate the ROUTE INDEX section of `docs/api-reference.md` from the route-table
 * snapshots (`src/generated/route-table/<service>.json`).
 *
 * The hand-written endpoint tables above the index describe request and response
 * shapes, and nothing forces them to name every route: when a survey counted, 67
 * plugin routes and about 16 pipeline routes appeared in no doc at all, and the
 * Ask service had no section. The snapshots are regenerated by each service's
 * route-coverage test (`UPDATE_ROUTE_TABLES=1`), so an index built from them can't
 * miss a route — and `test/api-reference-generated.test.ts` runs this script with
 * `--check`, so a new route without a regenerated index fails the build.
 *
 * Only the text between the BEGIN/END markers is owned by this script; the rest of
 * the doc stays hand-written.
 *
 * Left out of the index, on purpose:
 *  - the probes (`/health`, `/ready`, `/metrics`, `/warmup`) — infrastructure, not API;
 *  - routes reachable only by named internal services (`internalCallers`), which
 *    no user credential can reach (see "Internal routes are not part of this API").
 *
 * Run: `npm run generate:api-reference` (from frontend/). Idempotent.
 * `--check` writes nothing and exits 1 when the doc is stale.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const FRONTEND = join(HERE, '..');
const TABLES = join(FRONTEND, 'src', 'generated', 'route-table');
const DOC = process.env.API_REFERENCE_DOC ?? join(FRONTEND, '..', 'docs', 'api-reference.md');

export const BEGIN = '<!-- BEGIN GENERATED: route-index (frontend/scripts/generate-api-reference.mjs) -->';
export const END = '<!-- END GENERATED: route-index -->';

/** Services indexed, in doc order: [route-table file, heading]. */
const SERVICES = [
  ['pipeline', 'Pipeline Service'],
  ['plugin', 'Plugin Service'],
  ['ask', 'Ask Service'],
];

const PROBES = new Set(['/health', '/ready', '/metrics', '/warmup']);

/** Routes whose authorization the table flags can't express. */
const NOTES = {
  'GET /logs/:requestId': 'SSE build-log stream; authorized by a short-lived `?ticket=` from `POST /logs/ticket`, not a bearer token',
};

const code = (s) => `\`${s}\``;

/** Everything a route demands of its caller, in one cell. */
function requires(e) {
  const parts = [];
  if (!e.auth) parts.push('no bearer token');
  if (e.systemAdmin) parts.push('superadmin');
  if (e.systemOrg) parts.push('system org');
  if (e.servicePrincipal) parts.push('service principal');
  for (const g of e.permissions ?? []) {
    const joined = [...g.permissions].sort().map(code).join(g.mode === 'all' ? ' + ' : ' or ');
    parts.push(g.allowService ? `${joined} (service accounts too)` : joined);
  }
  if (e.dynamicAuthz?.length) parts.push('decided per request');
  if (e.minAssurance >= 2) parts.push('MFA session (aal2)');
  else if (e.minAssurance === 1) parts.push('a person (no service account or access key)');
  if (e.stepUp) parts.push('step-up');
  for (const f of e.features ?? []) parts.push(`feature ${code(f)}`);
  for (const s of e.scopes ?? []) parts.push(`scope ${code(s)}`);
  const note = NOTES[`${e.method} ${e.path}`];
  if (note) parts.push(note);
  return parts.length ? parts.join('; ') : 'signed in';
}

function row(e) {
  const meters = e.quota?.metered?.length ? e.quota.metered.map(code).join(', ') : '—';
  const audit = e.audit?.length ? e.audit.map(code).join(', ') : '—';
  // A `|` inside a cell would split it; none of the inputs carry one, but be safe.
  const cell = (s) => s.replace(/\|/g, '\\|');
  return `| ${code(e.method)} | ${code(e.path)} | ${cell(requires(e))} | ${meters} | ${cell(audit)} |`;
}

export function renderIndex() {
  const out = [BEGIN, ''];
  for (const [file, heading] of SERVICES) {
    const entries = JSON.parse(readFileSync(join(TABLES, `${file}.json`), 'utf8'))
      .filter((e) => !PROBES.has(e.path) && !(e.internalCallers?.length));
    out.push(`### ${heading} — every route`, '');
    out.push(`${entries.length} routes, from \`frontend/src/generated/route-table/${file}.json\`.`, '');
    out.push('| Method | Endpoint | Requires | Meters | Audit action |', '|--------|----------|----------|--------|--------------|');
    for (const e of entries) out.push(row(e));
    out.push('');
  }
  out.push(END);
  return out.join('\n');
}

/** The doc with its marked section replaced by a fresh render. */
export function renderDoc(doc) {
  const start = doc.indexOf(BEGIN);
  const end = doc.indexOf(END);
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`docs/api-reference.md is missing the route-index markers (${BEGIN} … ${END})`);
  }
  return doc.slice(0, start) + renderIndex() + doc.slice(end + END.length);
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const current = readFileSync(DOC, 'utf8');
  const next = renderDoc(current);
  if (process.argv.includes('--check')) {
    if (next !== current) {
      process.stderr.write('docs/api-reference.md route index is stale: run `npm run generate:api-reference` in frontend/.\n');
      process.exit(1);
    }
  } else if (next !== current) {
    writeFileSync(DOC, next);
  }
}
